#!/usr/sbin/nft -f
flush ruleset
table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
    iif lo accept
    # database accepts PostgreSQL only from the application zone
    ip saddr 10.10.0.0/24 tcp dport 5432 accept
    # SSH only from the management zone
    ip saddr 10.99.0.0/24 tcp dport 22 accept
    limit rate 5/minute log prefix "nft-drop: "
  }
}

